TITLES = {1: 'Melekler Kimdir?', 2: 'Meleklerin Özellikleri', 3: 'Cebrâil ve Vahiy', 4: "Kur'an'da Meleklerin Görevleri", 5: 'Meleklere İmanın Anlamı', 6: 'Yanlış Anlamaları Düzelt', 7: 'Melekler Ustalığı'}

Q = [
 ('mc', 1, 'p6_nur', 'Meleklere iman', 'e', 'Meleklerin yaratıldığı unsur İslamî kaynaklarda nasıl bildirilir?', 'Nur', ['Ateş', 'Toprak', 'Su'], 'Hadise göre melekler nurdan yaratılmıştır.'),
 ('mc', 1, 'p6_itaat', 'Meleklere iman', 'e', 'Melekler Allah’ın emirlerine karşı nasıl davranır?', 'İsyan etmez, emredileni yerine getirirler', ['İnsanlar gibi günah işlemekte serbesttirler', 'Kendi ilahlarını seçerler', 'Allah’ın emirlerini reddederler'], 'Melekler Allah’a isyan etmez, kendilerine emredileni yaparlar (Tahrîm 6).'),
 ('mc', 2, 'p6_cebrail', 'Meleklere iman', 'e', 'Vahiy getirmekle görevli melek kimdir?', 'Cebrâil', ['Mikâil', 'Azrâil', 'İsrâfil'], 'Cebrâil, Allah’ın vahyini peygamberlere ulaştıran melektir.'),
 ('mc', 2, 'p6_mikail', 'Meleklere iman', 'm', 'Tabiat olayları ve rızıkla ilgili görevlerle anılan melek kimdir?', 'Mikâil', ['Cebrâil', 'Mâlik', 'İsrâfil'], 'Mikâil, yağmur ve rızık gibi görevlerle anılır.'),
 ('mc', 2, 'p6_israfil', 'Meleklere iman', 'm', 'Sûra üflemekle görevli melek kimdir?', 'İsrâfil', ['Cebrâil', 'Mikâil', 'Kirâmen Kâtibîn'], 'İsrâfil, kıyametin kopması için sûra üfleyecek melektir.'),
 ('mc', 3, 'p6_azrail', 'Meleklere iman', 'm', 'Can almakla görevli melek hangi adla bilinir?', 'Melekü’l-mevt', ['Cebrâil', 'İsrâfil', 'Mikâil'], 'Can almakla görevli melek, Kur’an’da “Melekü’l-mevt” (ölüm meleği) diye anılır; halk arasında Azrâil denir.'),
 ('mc', 3, 'p6_kiramen', 'Meleklere iman', 'm', 'İnsanların iyi ve kötü davranışlarını yazmakla görevli melekler nasıl adlandırılır?', 'Kirâmen Kâtibîn', ['Zebânîler', 'Mukarrebûn', 'Hamele-i Arş'], 'Kirâmen Kâtibîn, insanların davranışlarını kaydeden değerli yazıcı meleklerdir (İnfitâr 10-12).'),
 ('mc', 4, 'p6_munker', 'Meleklere iman', 'm', 'Kabir sorgusuyla ilişkilendirilen melekler hangileridir?', 'Münker ve Nekir', ['Cebrâil ve Mikâil', 'İsrâfil ve Azrâil', 'Hârût ve Mârût'], 'Hadislerde kabirde sorgu yapan melekler Münker ve Nekir olarak anılır.'),
 ('mc', 4, 'p6_ridvan', 'Meleklere iman', 'm', 'Cennet bekçisi olarak anılan meleğin adı hangisidir?', 'Rıdvan', ['Cebrâil', 'Mâlik', 'Mikâil'], 'Cennet görevlisi melek Rıdvan adıyla anılır.'),
 ('mc', 5, 'p6_malik', 'Meleklere iman', 'm', 'Cehennem görevlisi olarak Kur’an’da adı geçen melek hangisidir?', 'Mâlik', ['Rıdvan', 'Mikâil', 'İsrâfil'], 'Zuhruf 77’de cehennem bekçisi olarak Mâlik’in adı geçer.'),
 ('mc', 5, 'p6_cinsiyet', 'Meleklere iman', 'h', 'Meleklerin cinsiyetleri hakkında İslamî yaklaşım hangisidir?', 'İnsanların cinsiyet kategorileriyle tanımlanmazlar', ['Hepsi erkektir', 'Hepsi kadındır', 'İnsanlarla aynı biyolojik yapıya sahiptirler'], 'Melekler, insanın cinsiyet kategorileriyle tanımlanmaz; Kur’an onlara dişi demeyi eleştirir (Zuhruf 19).'),
 ('mc', 6, 'p6_gayb', 'Meleklere iman', 'e', 'İslam inancına göre melekler hangi özelliğe sahiptir?', 'Gaybî varlıklardır', ['Her zaman insan gözüyle görülürler', 'Allah’a ortaktırlar', 'Yaratıcıdırlar'], 'Melekler, duyularla doğrudan algılanmayan gaybî varlıklardır.'),
 ('mc', 6, 'p6_dort_buyuk', 'Meleklere iman', 'm', 'Dört büyük melekten biri olmayan hangisidir?', 'Münker', ['Cebrâil', 'Mikâil', 'İsrâfil'], 'Dört büyük melek Cebrâil, Mikâil, İsrâfil ve Azrâil’dir.'),
 ('mc', 7, 'p6_izin', 'Meleklere iman', 'h', 'Meleklerin Allah’ın izni olmadan bağımsız güç kullanabildiğine inanmak doğru mudur?', 'Hayır; görevlerini Allah’ın emri ve izniyle yerine getirirler', ['Evet; yaratma gücüne sahiptirler', 'Evet; Allah’tan bağımsızdırlar', 'Hayır; çünkü melekler yoktur'], 'Melekler görevlerini Allah’ın emri ve izniyle yerine getirirler; bağımsız güç sahibi değildirler.'),
 ('mc', 7, 'p6_bilinc', 'Meleklere iman', 'm', 'Meleklere iman insanda hangi bilinci güçlendirebilir?', 'Davranışların kaydedildiği ve sorumluluk taşıdığı bilincini', ['İnsanların ilah olduğu inancını', 'Haksızlığın serbest olduğu fikrini', 'Hiçbir davranışın önemli olmadığı düşüncesini'], 'Meleklere iman, davranışların kaydedildiği bilincini ve sorumluluk duygusunu güçlendirir.'),
 ('mc', 1, 'b6_sayi', 'Meleklere iman', 'm', 'Kur’an’a göre meleklerin sayısı hakkında hangisi doğrudur?', 'Rabbinin ordularını ancak kendisi bilir', ['Sayıları yalnızca yedidir', 'Sayıları insanlardan azdır', 'Sayıları hiç bilinmez ama yoktur'], 'Müddessir 31’de “Rabbinin ordularını O’ndan başkası bilmez” buyrulur.'),
 ('mc', 1, 'b6_arsi', 'Meleklere iman', 'h', 'Kur’an’a göre kıyamet günü Rabbinin arşını kaç melek taşıyacaktır?', 'Sekiz', ['İki', 'Dört', 'Oniki'], 'Hâkka 17’de o gün Rabbinin arşını onların üstünde sekiz meleğin taşıyacağı bildirilir.'),
 ('mc', 1, 'b6_cehennem_19', 'Meleklere iman', 'h', 'Müddessir Suresi’ne göre cehennemin bekçileri kaç melektir?', 'Ondokuz', ['Yedi', 'Onbir', 'Kırk'], 'Müddessir 30’da cehennem üzerinde ondokuz meleğin görevli olduğu bildirilir.'),
 ('mc', 2, 'b6_kanat', 'Meleklere iman', 'm', 'Fâtır Suresi’ne göre melekler nasıl tanıtılır?', 'İkişer, üçer, dörder kanatlı elçiler olarak', ['Tek kanatlı varlıklar olarak', 'Kanatsız varlıklar olarak', 'Yalnızca insan suretinde varlıklar olarak'], 'Fâtır 1’de melekler ikişer, üçer, dörder kanatlı elçiler olarak anılır.'),
 ('mc', 2, 'b6_cin_melek', 'Meleklere iman', 'm', 'Kur’an’a göre İblis hangi türdendir?', 'Cinlerdendir', ['Meleklerdendir', 'İnsanlardandır', 'Hayvanlardandır'], 'Kehf 50’de İblis’in cinlerden olduğu bildirilir.'),
 ('mc', 2, 'b6_nur_ates', 'Meleklere iman', 'e', 'Hadise göre melekler, cinler ve insan nelerden yaratılmıştır?', 'Melekler nurdan, cinler ateşten, insan topraktan', ['Hepsi topraktan', 'Melekler ateşten, cinler nurdan', 'Hepsi sudan'], 'Hadise göre melekler nurdan, cinler ateşten, Âdem topraktan yaratılmıştır (Müslim).'),
 ('mc', 2, 'b6_yemez', 'Meleklere iman', 'm', 'Meleklerle ilgili hangisi doğrudur?', 'Evlenmezler; erkeklik ve dişilikle nitelenmezler', ['Yer içerler', 'Evlenip çocuk sahibi olurlar', 'Ölüp yeniden doğarlar'], 'Melekler evlenmez ve cinsiyetle nitelenmez; nuranî varlıklardır.'),
 ('mc', 3, 'b6_ruh_emin', 'Meleklere iman', 'e', 'Kur’an’da Cebrâil’e verilen unvanlardan biri hangisidir?', 'er-Rûhu’l-Emîn (güvenilir ruh)', ['el-Gaffâr', 'el-Basîr', 'er-Rezzâk'], 'Şuarâ 193’te Cebrâil “er-Rûhu’l-Emîn” diye anılır.'),
 ('mc', 3, 'b6_meryem', 'Meleklere iman', 'm', 'Cebrâil, Hz. Meryem’e hangi suretle görünmüştür?', 'Düzgün bir insan suretinde', ['Bir kuş suretinde', 'Bir ışık suretinde', 'Bir bulut suretinde'], 'Meryem 17’de Cebrâil, Meryem’e tam bir insan şeklinde görünür.'),
 ('mc', 3, 'b6_asil_suret', 'Meleklere iman', 'h', 'Hz. Peygamber, Cebrâil’i asıl suretinde kaç defa görmüştür?', 'İki defa', ['Hiç görmemiştir', 'Yüz defa', 'Her gün'], 'Necm 13-14 ve hadislere göre Cebrâil’i asıl suretinde iki defa görmüştür.'),
 ('mc', 3, 'b6_ruhulkudus', 'Meleklere iman', 'm', 'Bakara Suresi’nde Hz. Îsâ’yı destekleyen “Rûhu’l-Kudüs” genellikle kim olarak anlaşılır?', 'Cebrâil', ['Mikâil', 'İsrâfil', 'Münker'], 'Bakara 87’deki “Rûhu’l-Kudüs” çoğunlukla Cebrâil olarak yorumlanır.'),
 ('mc', 3, 'b6_bedir', 'Meleklere iman', 'm', 'Bedir Savaşı’nda Müslümanlara Kur’an’a göre hangi yardım ulaşmıştır?', 'Melekler indirilerek destek verilmiştir', ['Yağmur yerine kar yağmıştır', 'Düşman ordusu kendiliğinden dağılmıştır', 'Hiçbir yardım gelmemiştir'], 'Enfâl 9 ve Âl-i İmrân 123-125’te Bedir’de meleklerle yardım edildiği bildirilir.'),
 ('mc', 3, 'b6_ibrahim_misafir', 'Meleklere iman', 'm', 'Hz. İbrahim’e misafir olarak gelen ve ona müjde veren varlıklar kimlerdir?', 'Melekler', ['Cinler', 'Hayvanlar', 'Peygamberler'], 'Hûd 69-70’te insan suretindeki melekler İbrahim’e müjde getirir.'),
 ('mc', 4, 'b6_sag_sol', 'Meleklere iman', 'm', 'Kâf Suresi’ne göre insanın amellerini yazan melekler nerede bulunur?', 'Sağında ve solunda oturur', ['Başının üstünde uçar', 'Ayaklarının altında durur', 'Gökte kalır'], 'Kâf 17-18’de sağda ve solda oturan iki kayıtçı melek bildirilir.'),
 ('mc', 4, 'b6_rakib_atid', 'Meleklere iman', 'h', 'Kâf 18’de insanın söylediklerini kaydeden meleklerin sıfatları nelerdir?', 'Rakîb ve Atîd (gözetleyen ve hazır bekleyen)', ['Kerîm ve Latîf', 'Kavî ve Metîn', 'Evvel ve Âhir'], 'Kâf 18’de meleklerden “rakîb” ve “atîd” diye söz edilir.'),
 ('mc', 4, 'b6_adem_secde', 'Meleklere iman', 'm', 'Bakara Suresi’ne göre Allah, meleklere Hz. Âdem için ne emretmiştir?', 'Secde etmelerini', ['Onu dışlamalarını', 'Ona öğretmenlik etmelerini', 'Onu korumalarını yasaklamayı'], 'Bakara 34’te meleklere Âdem’e secde etmeleri emredilir; İblis hariç hepsi secde eder.'),
 ('mc', 4, 'b6_kadir_inis', 'Meleklere iman', 'm', 'Kadir Suresi’ne göre Kadir Gecesi’nde melekler ve Rûh ne yapar?', 'Rablerinin izniyle iner', ['Gökte gizlenir', 'Yeryüzünden ayrılır', 'Kabirlere girer'], 'Kadr 4’te melekler ve Rûh’un Rablerinin izniyle indikleri bildirilir.'),
 ('mc', 4, 'b6_istigfar', 'Meleklere iman', 'h', 'Arşı taşıyan melekler, Mü’min Suresi’ne göre kimler için dua eder?', 'İman edenler için bağışlanma diler', ['Yalnızca kendileri için', 'Kâfirler için', 'Sadece peygamberler için'], 'Mü’min 7’de arşı taşıyan meleklerin müminler için bağışlanma dilediği bildirilir.'),
 ('mc', 4, 'b6_mueminlere_korkma', 'Meleklere iman', 'm', 'Fussilet 30’a göre “Rabbimiz Allah’tır” deyip dosdoğru olanlara melekler ne der?', 'Korkmayın, üzülmeyin, size vaat edilen cennetle sevinin', ['Dünyada kalın, ölmeyeceksiniz', 'Yalnız kalacaksınız', 'Hesaptan kurtulamazsınız'], 'Fussilet 30’da melekler istikamet üzere olanlara korku ve üzüntüden uzak olmalarını söyler.'),
 ('mc', 5, 'b6_koyunlar', 'Meleklere iman', 'm', 'Hadise göre köpek veya canlı resmi bulunan eve ne olur?', 'Melekler (rahmet melekleri) girmez', ['Melekler orada konaklar', 'Melekler orada zikreder', 'Evin rızkı artar'], 'Hadise göre köpek veya canlı resmi bulunan eve rahmet melekleri girmez (Buhârî).'),
 ('mc', 5, 'b6_beytulmamur', 'Meleklere iman', 'h', 'Mirac olayında Hz. Peygamber’e gösterilen, her gün çok sayıda meleğin ibadet ettiği yer neresidir?', 'Beytü’l-Ma‘mûr', ['Mescid-i Aksa', 'Hira Mağarası', 'Kuba Mescidi'], 'Hadislere göre Mirac’da Beytü’l-Ma‘mûr gösterilmiş, orada her gün yetmiş bin melek ibadet etmiştir.'),
 ('mc', 5, 'b6_kizlar', 'Meleklere iman', 'h', 'Kur’an, “Melekler Allah’ın kızlarıdır” iddiasına nasıl yaklaşır?', 'Bu iddiayı reddeder', ['Doğrular', 'Hiç bahsetmez', 'Yalnızca bazı melekler için kabul eder'], 'Kur’an, meleklere dişi demeyi ve Allah’a kız isnat etmeyi reddeder (İsrâ 40, Zuhruf 19).'),
 ('mc', 5, 'x6_tesbih', 'Meleklerin tesbihi', 'm', 'Enbiyâ 20’ye göre melekler Allah’ı nasıl tesbih eder?', 'Gece gündüz usanmadan', ['Yalnızca gündüz', 'Yalnızca cuma günleri', 'Yılda bir kez'], 'Enbiyâ 20’de melekler gece gündüz usanmadan Allah’ı tesbih eder.'),
 ('mc', 5, 'b6_inkar', 'Meleklere iman', 'h', 'Meleklerin varlığını inkâr etmek İslam inancında nasıl değerlendirilir?', 'İmanın bir esasını inkâr sayılır', ['Hiçbir sonucu yoktur', 'Sadece bir görüş farkıdır', 'Küçük bir günahtır'], 'Bakara 285 ve Nisâ 136’ya göre meleklere iman, imanın esasıdır; inkârı iman esasını reddetmektir.'),
 ('mc', 5, 'b6_lut', 'Meleklere iman', 'm', 'Hz. Lût’un kavmine azap getirmek için gönderilen varlıklar kimlerdir?', 'Melekler', ['Cinler', 'Kuşlar', 'Rüzgârlar'], 'Hûd 77-83’te Lût kavminin helâki için melekler gönderilmiştir.'),
 ('mc', 6, 'b6_zekeriyya', 'Meleklere iman', 'm', 'Hz. Zekeriyya’ya oğlu Yahyâ’nın müjdesini kim vermiştir?', 'Melekler', ['Cinler', 'Bir kervan', 'Yaşlı bir kâhin'], 'Âl-i İmrân 39’da melekler, Zekeriyya’ya Yahyâ’yı müjdeler.'),
 ('mc', 6, 'b6_saf_saf', 'Meleklere iman', 'h', 'Fecr Suresi’ne göre kıyamet gününde melekler nasıl gelir?', 'Saf saf dizilmiş olarak', ['Dağınık olarak', 'Tek tek ve gizlice', 'Yeryüzünden yükselerek'], 'Fecr 22’de Rabbin ve melekler saf saf geleceği bildirilir.'),
 ('mc', 6, 'b6_amin', 'Meleklere iman', 'e', 'Hadise göre biri “âmin” dediğinde melekler ne yapar?', 'O da “âmin” der', ['Susar', 'Gökyüzüne çekilir', 'Yazıdan çıkarır'], 'Hadise göre imam ve cemaat “âmin” deyince melekler de âmin der; âmini meleklere denk gelenin günahları bağışlanır (Buhârî).'),
 ('mc', 6, 'b6_melek_isyan', 'Meleklere iman', 'm', 'Hârût ve Mârût haberi hangi surede geçer?', 'Bakara Suresi', ['Yâsîn Suresi', 'Kehf Suresi', 'Nûr Suresi'], 'Hârût ve Mârût, Bakara 102’de Babil’de insanlara öğretilen sihir bağlamında anılır.'),
 ('mc', 6, 'b6_muhafaza', 'Meleklere iman', 'h', 'Ra‘d 11’e göre insanın önünden ve ardından gelen, onu Allah’ın emriyle koruyan varlıklar kimlerdir?', 'Takipçi melekler (muakkibât)', ['Cinler', 'Kuşlar', 'Rüzgârlar'], 'Ra‘d 11’de insanı Allah’ın emriyle koruyan, peş peşe gelen melekler anılır.'),
 ('mc', 7, 'b6_secde_ibadet', 'Meleklere iman', 'h', 'Meleklerin Hz. Âdem’e secde etmesi neyi ifade eder?', 'Allah’a itaat ve Âdem’e saygı', ['Âdem’in ilahlığını', 'Meleklerin Allah’a isyanını', 'Âdem’in meleklerin yaratıcısı olduğunu'], 'Melekler Allah’ın emrine uyarak Âdem’e saygı secdesi etmiştir; ibadet değildir.'),
 ('mc', 7, 'b6_fark', 'Meleklere iman', 'm', 'Melek, cin ve insan arasındaki farklardan biri hangisidir?', 'Melekler günah işlemez; cin ve insanın iradesi vardır ve sorumludurlar', ['Hepsi aynı unsurdan yaratılmıştır', 'Yalnızca insan sorumludur', 'Yalnızca melekler yer ve içer'], 'Melekler isyan etmez; cin ve insan ise iradeleri ölçüsünde sorumludur.'),
 ('mc', 7, 'b6_duasi', 'Meleklere iman', 'm', 'Hz. Peygamber’e göre melekler müminin kardeşi için gıyabında yaptığı duaya ne der?', '“Sana da aynısı olsun” der', ['Hiçbir şey demez', 'Duayı yazmaz', '“Hayır” der'], 'Hadise göre kardeşi için gıyabında dua edene melek “sana da aynısı” der (Müslim).'),
 ('mc', 7, 'b6_cin_sure', 'Meleklere iman', 'e', 'Kur’an’da cinlerle ilgili adı verilen sure hangisidir?', 'Cin Suresi', ['Fil Suresi', 'Kevser Suresi', 'Asr Suresi'], 'Kur’an’ın 72. suresi Cin Suresi’dir.'),
 ('mc', 7, 'b6_cebrail_mukabele', 'Meleklere iman', 'h', 'Hadise göre Cebrâil, Ramazan aylarında Hz. Peygamber’le ne yapardı?', 'Kur’an’ı karşılıklı okurdu (mukabele)', ['Ona hac öğretirdi', 'Onunla savaşa giderdi', 'Ona oruç tutturmazdı'], 'Cebrâil her Ramazan Hz. Peygamber’le Kur’an’ı karşılıklı okur, vefat yılında iki kez okumuşlardır (Buhârî).'),
]
